import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Check {

    private static int failures = 0;

    static void eq(int total, List<Integer> coins, Integer... expected) {
        try {
            List<Integer> actual = new ChangeCalculator(coins).computeMostEfficientChange(total);
            if (actual.equals(Arrays.asList(expected))) {
                System.out.println("PASS " + total + " " + coins + " -> " + actual);
            } else {
                failures++;
                System.out.println("FAIL " + total + " " + coins + " -> " + actual
                        + " expected " + Arrays.asList(expected));
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL " + total + " " + coins + " threw " + e);
        }
    }

    static void err(int total, List<Integer> coins, String message) {
        try {
            List<Integer> actual = new ChangeCalculator(coins).computeMostEfficientChange(total);
            failures++;
            System.out.println("FAIL " + total + " " + coins + " returned " + actual
                    + " expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            if (message.equals(e.getMessage())) {
                System.out.println("PASS " + total + " " + coins + " -> IllegalArgumentException: " + e.getMessage());
            } else {
                failures++;
                System.out.println("FAIL wrong message: " + e.getMessage());
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL " + total + " " + coins + " threw " + e);
        }
    }

    public static void main(String[] args) {
        List<Integer> us = Arrays.asList(1, 5, 10, 25);
